import React from 'react'
import PropTypes from 'prop-types'
import { throwError } from 'cerebral'
import { DEPRECATE } from 'cerebral/internal'
import { ControllerContext } from '@cerebral/react/src/context'

class Container extends React.Component {
  render() {
    const { app, controller, children } = this.props

    if (controller) {
      DEPRECATE(
        'Container',
        'please change from "controller" to "app" property'
      )
    }

    if (!app && !controller) {
      throwError('You are not passing a Cerebral app to Container')
    }

    const controllerInstance = app || controller

    return (
      <ControllerContext.Provider value={controllerInstance}>
        {children}
      </ControllerContext.Provider>
    )
  }
}

Container.propTypes = {
  app: PropTypes.object,
  controller: PropTypes.object,
  children: PropTypes.node.isRequired,
}

export default Container
